#+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
# This is an EXUDYN maintainer tool
#
# Details:  Runs every code generator and reports whether the committed generated files still
#           match what the generators produce. Tier 1 (the API surface) is a hard gate; Tier 2
#           (documentation) warns only. See docs/revision/exudynRevisionPlan2026.md section 4.
#
#           IMPORTANT: run this AFTER issueTracker.ResolveIssue(), never before. ResolveIssue
#           rewrites version.txt, and README.rst and docs/RST/Exudyn.rst embed the
#           version string, so regenerating first leaves them one version behind and this tool
#           then reports drift unrelated to your change (revision2026 fact 21).
#
#           Before running the generators it validates definitions/ (definitionValidator.py)
#           and stops with exit code 3 if they are inconsistent.
#
# Usage:    python tools/regenerate.py            regenerate and report
#           python tools/regenerate.py --check    the same, but exit non-zero on Tier 1 drift (CI)
#           python tools/regenerate.py --no-run   only check drift, do not run the generators
#
# Author:   Johannes Gerstmayr
# Date:     2026-09-09 (created)
# Copyright:This file is part of Exudyn. Exudyn is free software: see 'LICENSE.txt'
#
#+++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++

import argparse
import subprocess
import sys
import os

#reuse the generators' own comparison rule rather than reimplementing the date exclusion:
#lines starting with '* @date' or '// AUTO:  last modified' are volatile within otherwise
#stable files, so git status alone reports phantom drift once a file has been rewritten
sys.path.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'generators'))
from autoGenerateHelper import IsEqualIgnoringDateStrings

#the generators, their order and their inputs/outputs are declared in tools/generators/generate.py,
#the single driver (revision2026 step R4.3, part 2f); this tool runs it and compares with the commit
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), 'generators'))
import generate


#Tier 1: the API surface. Any difference here is a hard failure.
tier1Paths = [
    'src/Autogenerated',
    'python/exudyn/itemInterface.py',
    'python/exudyn/types/items.py',
    'python/exudyn/__init__.pyi',
    'python/exudyn/symbolic.pyi',
    'tools/generators/generated',
    'python/MiniExamples',
    ]

#Tier 2: documentation. Differences warn but do not fail.
tier2Paths = [
    'docs/theDoc/itemDefinition.tex',
    'docs/theDoc/interfaces.tex',
    'docs/theDoc/manual_interfaces.tex',
    'docs/theDoc/pythonUtilitiesDescription.tex',
    'docs/theDoc/MainSystemExt.tex',
    'docs/theDoc/MainSystemCreateExt.tex',
    'docs/RST',
    'index.rst',
    'README.rst',
    ]

#written by issueTracker.py, not by the generators; excluded from both tiers so that a version
#bump is never reported as generator drift
excludedPaths = [
    'docs/RST/trackerlog.rst',
    'docs/theDoc/trackerlog.tex',
    'version.txt',
    'docs/theDoc/versionName.txt',
    'src/Autogenerated/versionCpp.cpp',
    ]


#%%******************************************************************************************************
def GetRepositoryRoot():
    """Absolute path of the repository root, independent of the current working directory."""
    result = subprocess.run(['git', 'rev-parse', '--show-toplevel'],
                            capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError('not inside a git repository: ' + result.stderr.strip())

    return os.path.normpath(result.stdout.strip())


#%%******************************************************************************************************
def GetChangedFiles(repositoryRoot, paths=None):
    """Set of repository-relative paths that differ from HEAD, optionally limited to 'paths'."""
    command = ['git', 'status', '--porcelain', '--untracked-files=all']
    if paths is not None:
        command += ['--'] + list(paths)

    result = subprocess.run(command, capture_output=True, text=True, cwd=repositoryRoot)
    if result.returncode != 0:
        raise RuntimeError('git status failed: ' + result.stderr.strip())

    changedFiles = set()
    for line in result.stdout.splitlines():
        if len(line) < 4:
            continue
        name = line[3:].strip().strip('"')
        #renames are reported as 'old -> new'; the new name is the interesting one
        if ' -> ' in name:
            name = name.split(' -> ')[-1]
        changedFiles.add(name)

    return changedFiles


#%%******************************************************************************************************
def DiffersIgnoringDates(repositoryRoot, fileName):
    """
    True if the working copy of fileName really differs from HEAD, ignoring the volatile
    '@date ... (last modified)' lines that every generated file carries. A file that was
    rewritten with identical content still shows in git status; that is not drift.
    """
    result = subprocess.run(['git', 'show', 'HEAD:' + fileName],
                            capture_output=True, cwd=repositoryRoot)
    if result.returncode != 0:
        return True     #not in HEAD: newly generated file, a real difference

    fullName = os.path.join(repositoryRoot, fileName)
    if not os.path.isfile(fullName):
        return True     #deleted, a real difference

    try:
        headText = result.stdout.decode('utf8')
        with open(fullName, 'r', encoding='utf8') as f:
            workingText = f.read()
    except UnicodeDecodeError:
        return True     #binary or non-UTF-8: cannot compare textually, report it

    #git normalises line endings in the object store; compare on LF
    headText = headText.replace('\r\n', '\n')
    workingText = workingText.replace('\r\n', '\n')

    return not IsEqualIgnoringDateStrings(headText, workingText)


#%%******************************************************************************************************
def IsExcluded(fileName):
    """True if the file is not generator output: owned by another tool, or a hand-placed note."""
    normalized = fileName.replace('\\', '/')
    if normalized in excludedPaths:
        return True

    #directory notes: the project marks folders with a '#what belongs here.txt' file. They live
    #inside generated directories but are hand-maintained, so they are not generator output.
    baseName = normalized.split('/')[-1]

    return baseName.startswith('#')


#%%******************************************************************************************************
def SelectDrift(changedFiles, paths):
    """Subset of changedFiles that lies under any of the given paths, excluding tool-owned files."""
    selected = set()
    for fileName in changedFiles:
        normalized = fileName.replace('\\', '/')
        if IsExcluded(normalized):
            continue
        for path in paths:
            if normalized == path or normalized.startswith(path + '/'):
                selected.add(normalized)
                break

    return selected


#%%******************************************************************************************************
def ReportDrift(title, driftFiles, limit=40):
    print(title + ': ' + str(len(driftFiles)) + ' file(s)')
    for fileName in sorted(driftFiles)[:limit]:
        print('    ' + fileName)
    if len(driftFiles) > limit:
        print('    ... and ' + str(len(driftFiles)-limit) + ' more')


#%%******************************************************************************************************
def Main():
    parser = argparse.ArgumentParser(
        description='Regenerate all Exudyn generated files and check them against the commit.')
    parser.add_argument('--check', action='store_true',
                        help='exit non-zero when Tier 1 files differ (use in CI)')
    parser.add_argument('--no-run', action='store_true',
                        help='do not run the generators, only check the current tree for drift')
    parser.add_argument('--python', default=sys.executable,
                        help='python executable used to run the generators (default: this one)')
    parser.add_argument('--quiet', action='store_true', help='less output')
    args = parser.parse_args()

    verbose = not args.quiet
    repositoryRoot = GetRepositoryRoot()
    if verbose:
        print('repository       : ' + repositoryRoot)
        print('python           : ' + args.python)

    #Files outside the two tiers that were already modified are unrelated work and are ignored.
    #Files INSIDE a tier are never excused by pre-existing dirtiness: an uncommitted or
    #hand-edited generated file is itself what this gate exists to catch.
    filesDirtyBefore = GetChangedFiles(repositoryRoot)
    unrelatedBefore = filesDirtyBefore - SelectDrift(filesDirtyBefore, tier1Paths + tier2Paths)
    if unrelatedBefore and verbose:
        print('note             : ' + str(len(unrelatedBefore))
              + ' file(s) modified outside the tiers; ignored as unrelated work')

    if not args.no_run:
        #the definitions are validated BEFORE anything is generated from them (revision2026 step R4.2)
        sys.path.insert(0, os.path.join(repositoryRoot, 'tools', 'generators'))
        import definitionValidator
        if definitionValidator.ValidateDefinitions(verbose=verbose):
            print('FAILED: the definitions in definitions/ are inconsistent; nothing was generated')
            return 3

        failedScripts = generate.RunStages(args.python, verbose=verbose)
        if failedScripts:
            print('FAILED: ' + str(len(failedScripts)) + ' generator(s) did not run: '
                  + ', '.join(failedScripts))
            return 2

    candidates = GetChangedFiles(repositoryRoot) - unrelatedBefore

    #git status flags a rewritten file even when only its timestamp line changed; keep only
    #the files that really differ
    changed = set([f for f in candidates if DiffersIgnoringDates(repositoryRoot, f)])
    dateOnly = candidates - changed
    if dateOnly and verbose:
        #either a volatile '@date ... (last modified)' line, or line endings only - the latter
        #happens when a Linux container rebuilds generated files inside a Windows working tree
        print('note             : ' + str(len(dateOnly))
              + ' file(s) differ only in date lines or line endings; not drift')

    tier1Drift = SelectDrift(changed, tier1Paths)
    tier2Drift = SelectDrift(changed, tier2Paths)
    otherDrift = changed - tier1Drift - tier2Drift
    otherDrift = set([f for f in otherDrift if not IsExcluded(f)])

    print('')
    if not tier1Drift and not tier2Drift and not otherDrift:
        print('OK: regeneration is a no-op; the committed generated set is current.')
        return 0

    if tier1Drift:
        ReportDrift('TIER 1 DRIFT (API surface, hard gate)', tier1Drift)
    if tier2Drift:
        ReportDrift('tier 2 drift (documentation, warning)', tier2Drift)
    if otherDrift:
        ReportDrift('drift outside both tiers (unexpected - check the manifest)', otherDrift)

    print('')
    if tier1Drift or otherDrift:
        print('Generated files differ from the commit. If the change was intended, commit it;')
        print('if not, a generator or its input has changed unexpectedly.')
        print('If only README.rst and docs/RST/Exudyn.rst differ, the version was bumped after')
        print('the last regeneration - see revision2026 fact 21, run this tool after ResolveIssue.')
        if args.check:
            return 1
    elif tier2Drift:
        print('Documentation differs from the commit; this is a warning, not a failure.')

    return 0


#%%******************************************************************************************************
if __name__ == '__main__':
    sys.exit(Main())
